mapper.select:
SELECT /* com.seinfo.seinfomationA.component.request.mapper.RequestMapper.selectRequestRegForm */ a.request_no , a.user_uid , b.login_id AS contact_login_id , a.request_title , a.request_detail , a.mfile_group_id , DATE_FORMAT(a.send_d, '%Y-%m-%d') AS send_d , a.request_state FROM seinfo_request a JOIN seinfo_vendor_manager b ON a.user_uid = b.user_uid WHERE request_no = #{requestNo}
AND b.user_email = #{userEmail}
AND IFNULL(b.user_pwd_init_yn,'N') != 'Y' AND b.bl_yn = 'N';

mapper.delete:
DELETE /* com.seinfo.seinfomationA.component.request.mapper.RequestMapper.deleteRequest */
FROM seinfo_request
WHERE request_no = #{requestNo}
  AND user_uid = #{userUid}
  AND request_state = #{requestState}

mapper.select:
SELECT /*com.seinfo.seinfomationA.component.request.mapper.RequestMapper.selectRequestFileGrpId */
	mfile_group_id as mfile_grp_id
FROM seinfo_request
WHERE request_no = #{requestNo}
  AND user_uid = #{userUid}
  AND request_state = #{requestState}
